-- Rank positions by seniority (lower = more senior) so staff lists show the most senior first.
ALTER TABLE `finance_positions` ADD COLUMN `seniority` SMALLINT UNSIGNED NOT NULL DEFAULT 90 AFTER `salary_grade`;
UPDATE `finance_positions` SET `seniority` = CASE WHEN CONCAT(' ', LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`name`, '(', ' '), ')', ' '), '-', ' '), '/', ' '), '.', ' '), ',', ' ')), ' ') LIKE '% assistant %' OR CONCAT(' ', LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`name`, '(', ' '), ')', ' '), '-', ' '), '/', ' '), '.', ' '), ',', ' ')), ' ') LIKE '% intern %' OR CONCAT(' ', LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`name`, '(', ' '), ')', ' '), '-', ' '), '/', ' '), '.', ' '), ',', ' ')), ' ') LIKE '% trainee %' OR CONCAT(' ', LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`name`, '(', ' '), ')', ' '), '-', ' '), '/', ' '), '.', ' '), ',', ' ')), ' ') LIKE '% attendant %' THEN 100 WHEN CONCAT(' ', LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`name`, '(', ' '), ')', ' '), '-', ' '), '/', ' '), '.', ' '), ',', ' ')), ' ') LIKE '% deputy %' THEN 40 WHEN CONCAT(' ', LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`name`, '(', ' '), ')', ' '), '-', ' '), '/', ' '), '.', ' '), ',', ' ')), ' ') LIKE '% chair %' OR CONCAT(' ', LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`name`, '(', ' '), ')', ' '), '-', ' '), '/', ' '), '.', ' '), ',', ' ')), ' ') LIKE '% chairman %' OR CONCAT(' ', LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`name`, '(', ' '), ')', ' '), '-', ' '), '/', ' '), '.', ' '), ',', ' ')), ' ') LIKE '% chairperson %' OR CONCAT(' ', LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`name`, '(', ' '), ')', ' '), '-', ' '), '/', ' '), '.', ' '), ',', ' ')), ' ') LIKE '% board %' THEN 10 WHEN CONCAT(' ', LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`name`, '(', ' '), ')', ' '), '-', ' '), '/', ' '), '.', ' '), ',', ' ')), ' ') LIKE '% chief executive %' OR CONCAT(' ', LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`name`, '(', ' '), ')', ' '), '-', ' '), '/', ' '), '.', ' '), ',', ' ')), ' ') LIKE '% ceo %' OR CONCAT(' ', LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`name`, '(', ' '), ')', ' '), '-', ' '), '/', ' '), '.', ' '), ',', ' ')), ' ') LIKE '% founder %' OR CONCAT(' ', LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`name`, '(', ' '), ')', ' '), '-', ' '), '/', ' '), '.', ' '), ',', ' ')), ' ') LIKE '% president %' THEN 20 WHEN CONCAT(' ', LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`name`, '(', ' '), ')', ' '), '-', ' '), '/', ' '), '.', ' '), ',', ' ')), ' ') LIKE '% managing director %' OR CONCAT(' ', LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`name`, '(', ' '), ')', ' '), '-', ' '), '/', ' '), '.', ' '), ',', ' ')), ' ') LIKE '% md %' THEN 30 WHEN CONCAT(' ', LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`name`, '(', ' '), ')', ' '), '-', ' '), '/', ' '), '.', ' '), ',', ' ')), ' ') LIKE '% chief %' OR CONCAT(' ', LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`name`, '(', ' '), ')', ' '), '-', ' '), '/', ' '), '.', ' '), ',', ' ')), ' ') LIKE '% cfo %' OR CONCAT(' ', LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`name`, '(', ' '), ')', ' '), '-', ' '), '/', ' '), '.', ' '), ',', ' ')), ' ') LIKE '% coo %' OR CONCAT(' ', LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`name`, '(', ' '), ')', ' '), '-', ' '), '/', ' '), '.', ' '), ',', ' ')), ' ') LIKE '% cto %' OR CONCAT(' ', LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`name`, '(', ' '), ')', ' '), '-', ' '), '/', ' '), '.', ' '), ',', ' ')), ' ') LIKE '% cmo %' OR CONCAT(' ', LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`name`, '(', ' '), ')', ' '), '-', ' '), '/', ' '), '.', ' '), ',', ' ')), ' ') LIKE '% cio %' THEN 40 WHEN CONCAT(' ', LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`name`, '(', ' '), ')', ' '), '-', ' '), '/', ' '), '.', ' '), ',', ' ')), ' ') LIKE '% director %' OR CONCAT(' ', LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`name`, '(', ' '), ')', ' '), '-', ' '), '/', ' '), '.', ' '), ',', ' ')), ' ') LIKE '% general manager %' THEN 50 WHEN CONCAT(' ', LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`name`, '(', ' '), ')', ' '), '-', ' '), '/', ' '), '.', ' '), ',', ' ')), ' ') LIKE '% head %' THEN 60 WHEN CONCAT(' ', LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`name`, '(', ' '), ')', ' '), '-', ' '), '/', ' '), '.', ' '), ',', ' ')), ' ') LIKE '% manager %' THEN 70 WHEN CONCAT(' ', LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`name`, '(', ' '), ')', ' '), '-', ' '), '/', ' '), '.', ' '), ',', ' ')), ' ') LIKE '% supervisor %' OR CONCAT(' ', LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`name`, '(', ' '), ')', ' '), '-', ' '), '/', ' '), '.', ' '), ',', ' ')), ' ') LIKE '% lead %' OR CONCAT(' ', LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`name`, '(', ' '), ')', ' '), '-', ' '), '/', ' '), '.', ' '), ',', ' ')), ' ') LIKE '% coordinator %' THEN 80 ELSE 90 END WHERE `seniority` = 90;
